// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        vm.deal(address(c), 100 ether);
        c.AdjustBetAmounts(amount);
        uint256 balance = address(c).balance;
        uint256 ethBalanceReturned = c.ethBalance();
        assertTrue(ethBalanceReturned == balance, "ethBalance should return full balance");
    }
}

